QUOTES.extend(json.loads(Path(__file__).with_name('additional_quotes.json').read_text()))

def quote_block(quote_id):
    q = next(q for q in QUOTES if q['id'] == quote_id)
    url = COLLECTION + q['page']
    ending = ' […]' if q['excerpt'] else ''
    beginning = '[…] ' if q.get('leading_excerpt') else ''
    return f'''<blockquote class="quote sourced-quote" cite="{url}"><p><a href="{url}">«{beginning}{esc(q['text'])}{ending}»</a></p><cite><a href="{url}">{esc(q['attribution'])}</a><span class="quote-origin">Источник: biblioteka3.ru · {esc(q['topic'])}</span></cite></blockquote>'''


def direct_quote_links(body):
    urls = {q['id']: COLLECTION + q['page'] for q in QUOTES}
    return re.sub(r'href="/tsitaty/#([a-z-]+)"', lambda m: f'href="{urls[m[1]]}"' if m[1] in urls else m[0], body)


def publish_quotes(page):
    census = json.loads(Path(__file__).with_name('quote_census.json').read_text())
    rows = ''.join(f'<tr><th><a href="{COLLECTION}{x["page"]}">{esc(x["topic"])}</a></th><td>{x["quotations"]}</td></tr>' for x in census['topics'])
    census_html = f'<section id="collection-count"><h2>Сколько цитат в исходной подборке?</h2><p>По подсчёту мастерской от 2 октября 2026 года — <strong>{census["total"]} отдельных цитат в восьми тематических разделах</strong>. На сайте сейчас использованы {len(QUOTES)} проверенных цитатных фрагментов из этой подборки.</p><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Раздел исходного сайта</th><th>Цитат</th></tr></thead><tbody>{rows}</tbody><tfoot><tr><th>Всего</th><td>{census["total"]}</td></tr></tfoot></table></div><p class="fine">Считаем отдельные цитатные записи, а не абзацы и не уникальные фразы после удаления повторов. В разделе о сребролюбии два абзаца содержат по две цитаты. Меню, случайные цитаты и другие сборники из «Смотрите также» не включены. Подсчёт относится к содержимому на дату проверки.</p></section>'
    sections = []
    for q in QUOTES:
        ending = ' […]' if q['excerpt'] else ''
        related = ''.join(f'<li><a href="/masterskaya/{slug}/#tradition">{esc(label)}</a></li>' for slug, label in q['lessons'])
        related_section = f'<h3>Встреча с литературой</h3><ul>{related}</ul>' if related else '<p><a href="/shkola/">Сопоставления в курсе по классам</a></p>'
        sections.append(f'''<section id="{q['id']}"><h2>{q['title']}</h2>
        {quote_block(q['id'])}
        <p class="fine">{esc(q['note'])}</p><p><a href="{COLLECTION}{q['page']}">Цитатник: «{q['topic']}»</a> · <a href="{q['work']}">Текст, на который ссылается цитатник</a></p>
        <h3>Комментарий мастерской</h3><p>{esc(q['comment'])}</p>{related_section}</section>''')
    body = f'''<div class="wrap"><div class="breadcrumb"><a href="/">Главная</a><span>/</span>Проверенные цитаты</div>
    <header class="page-title"><p class="eyebrow">Духовное чтение · источник и комментарий</p><h1>Слова, которым<br>нужна точность</h1><p class="lead">Святоотеческие и духовные цитаты мастерской берём только из выбранной подборки «Цитаты из творений святых отцов и других духовных авторов».</p></header>
    <article class="prose"><p><a href="{COLLECTION}">Открыть исходную подборку на biblioteka3.ru</a>. Проверенных фрагментов: {len(QUOTES)}. Они служат опорой для отдельных занятий и курса по классам. Это избранные высказывания, а не полный пересказ подборки.</p>
    {census_html}
    <h2>Как мы цитируем</h2><p>Сохраняем слова, орфографию и пунктуацию источника. Пропуск начала или продолжения обозначаем знаком […]. Под каждой цитатой оставляем подпись из подборки и ссылку на её тематическую страницу. Если указан только сборник, не подставляем имя автора по догадке.</p>
    <p>Комментарий мастерской отделён от цитаты. Сопоставление с литературой не означает, что духовный автор писал об этом произведении или что писатель опирался на данный текст. Литературные произведения и библейские тексты, которые мы разбираем, имеют собственные ссылки: это отдельные первоисточники.</p>
    <p class="fine">Первые фрагменты сверены 2 октября, дополнение — 9 октября 2026 года. Это сверка с указанной веб-подборкой, не текстологическая проверка по печатным изданиям. Подборка включает святых отцов и других духовных авторов: авторство каждого высказывания уточняем отдельно.</p>
    {''.join(sections)}
    <p><a href="/chtenie-i-tradiciya/">Как мы соединяем духовное чтение и литературный разбор</a></p></article></div>'''
